#!/usr/bin/env python3
"""Generate the parameter table and RTL offsets from the shared field list."""
import pathlib
import re
root = pathlib.Path(__file__).resolve().parents[1]
fields = re.findall(r'FIELD\((\w+),\s*(-?\d+),\s*"([^"]+)"\)',
                    (root/'include/dvrmc/config_fields.def').read_text())
lines = ['# Per-motor parameter registers', '',
         'Generated by `tools/generate_registers.py`; edit `config_fields.def`.', '',
         'Byte address = `0x100 + motor * 0x100 + offset`. All words are 32 bits.',
         'Writes are staged until COMMIT is accepted and a control tick occurs.', '',
         '| Offset | Field | Reset | Units / meaning |', '|---|---|---:|---|']
rtl=['// Generated parameter word offsets; base = 0x100 + motor*0x100.',
     '`ifndef DVRMC_REGISTERS_SVH', '`define DVRMC_REGISTERS_SVH']
for i,(name,default,meaning) in enumerate(fields):
    lines.append(f'| 0x{i*4:02x} | {name} | {default} | {meaning} |')
    rtl.append(f'`define DVRMC_{name} 32\'h{i*4:08x}')
rtl += ['`endif', '']
(root/'docs/parameters.md').write_text('\n'.join(lines)+'\n')
(root/'include/dvrmc/registers.svh').write_text('\n'.join(rtl))
